fqPB.prototype.varint = function(tag, value) {
  var t = BigInt(tag * 8 + 0);
  var v = BigInt(value);
  var out = [];
  var tv = t;
  while (tv > 0n) { var b = Number(tv & 0x7fn); tv >>= 7n; if (tv > 0n) b |= 0x80; out.push(b); }
  var vv = v;
  do { var b2 = Number(vv & 0x7fn); vv >>= 7n; if (vv > 0n) b2 |= 0x80; out.push(b2); } while (vv > 0n);
  for (var i = 0; i < out.length; i++) this.buf.push(out[i]);
  return this;
};
fqPB.prototype.string = function(tag, value) {
