  var tv = t;
  while (tv > 0n) { var b = Number(tv & 0x7fn); tv >>= 7n; if (tv > 0n) b |= 0x80; out.push(b); }
  var data = fqStrToBytes(value);
  var len = BigInt(data.length);
  var lv = len;
  do { var b2 = Number(lv & 0x7fn); lv >>= 7n; if (lv > 0n) b2 |= 0x80; out.push(b2); } while (lv > 0n);
  for (var i = 0; i < out.length; i++) this.buf.push(out[i]);
  for (var i = 0; i < data.length; i++) this.buf.push(data[i]);
  return this;
};
fqPB.prototype.bytes = function(tag, data) {
  var t = BigInt(tag * 8 + 2);
  var out = [];
  var tv = t;
  while (tv > 0n) { var b = Number(tv & 0x7fn); tv >>= 7n; if (tv > 0n) b |= 0x80; out.push(b); }
  var len = BigInt(data.length);
  var lv = len;
  do { var b2 = Number(lv & 0x7fn); lv >>= 7n; if (lv > 0n) b2 |= 0x80; out.push(b2); } while (lv > 0n);
  for (var i = 0; i < out.length; i++) this.buf.push(out[i]);
  for (var i = 0; i < data.length; i++) this.buf.push(data[i]);
