  var tv = t;
  while (tv > 0n) { var b = Number(tv & 0x7fn); tv >>= 7n; if (tv > 0n) b |= 0x80; out.push(b); }
  var len = BigInt(sub.buf.length);
  var lv = len;
  do { var b2 = Number(lv & 0x7fn); lv >>= 7n; if (lv > 0n) b2 |= 0x80; out.push(b2); } while (lv > 0n);
  for (var i = 0; i < out.length; i++) this.buf.push(out[i]);
