  var bodyHash = fqSM3Prefix6(xssStub === '' ? new Array(16).fill(0) : fqDecodeStub(xssStub));
  var queryHash = fqSM3Prefix6(query === '' ? new Array(16).fill(0) : fqStrToBytes(query));
  var rand = Math.floor(Math.random() * 0x7fffffff);
  var w = new fqPB();
  w.varint(1, 0x20200929 * 2);
  w.varint(2, 2);
  w.varint(3, rand);
  w.string(4, aid);
  w.string(5, deviceId);
  w.string(6, FQ_LICENSE_ID);
  w.string(7, versionName);
  w.string(8, FQ_SDK_VERSION);
  w.varint(9, FQ_SDK_VER_INT);
  w.bytes(10, new Array(8).fill(0));
  w.varint(11, 0);
  w.varint(12, timestamp * 2);
  w.bytes(13, bodyHash);
  w.bytes(14, queryHash);
  w.message(15, function(sub) {
    sub.varint(1, 1).varint(2, 1).varint(3, 1).varint(7, 3348294860);
  });
  w.string(16, '');
  w.string(20, 'none');
  w.varint(21, FQ_CALL_TYPE);
  w.message(23, function(sub) {
    sub.string(1, 'NX551J').varint(2, 8196).varint(4, 2162219008);
  });
  w.varint(25, 2);
  return w.toBytes();
}

function fqGetArgus(query, xssStub, timestamp) {
  var protobuf = fqPkcs7(fqBuildProtobuf(query, xssStub, timestamp), 16);
  // simon key = sm3(signKey || low || high || signKey)
  var sm3in = fqConcat(FQ_SIGN_KEY, FQ_LOW_RAND, FQ_HIGH_RAND, FQ_SIGN_KEY);
  var so = fqHexToBytes(fqSM3Bytes(sm3in));
  var sk = [];
  for (var i = 0; i < 32; i += 8) {
    var lo = 0n, hi = 0n;
    for (var j = 0; j < 4; j++) lo |= BigInt(so[i + j]) << BigInt(j * 8);
    for (var j = 0; j < 4; j++) hi |= BigInt(so[i + 4 + j]) << BigInt(j * 8);
    sk.push(lo + (hi << 32n));
  }
  var encrypted = new Array(protobuf.length);
  for (var off = 0; off < protobuf.length; off += 16) {
    var w0 = 0n, w1 = 0n;
    for (var j = 0; j < 8; j++) w0 |= BigInt(protobuf[off + j]) << BigInt(j * 8);
    for (var j = 0; j < 8; j++) w1 |= BigInt(protobuf[off + 8 + j]) << BigInt(j * 8);
    var res = fqSimonEnc([w0, w1], sk);
    var low = res[0], high = res[1];
    for (var j = 0; j < 8; j++) { encrypted[off + j] = Number((low >> BigInt(j * 8)) & 0xffn); encrypted[off + 8 + j] = Number((high >> BigInt(j * 8)) & 0xffn); }
  }
  var data = fqConcat(FQ_XOR_PREFIX, encrypted);
  for (var i = FQ_XOR_PREFIX.length; i < data.length; i++) data[i] ^= data[i % 8];
  var rev = [];
  for (var i = data.length - 1; i >= 0; i--) rev.push(data[i]);
  var header = [0xa6, 0x6e, 0xad, 0x9f, 0x77, 0x01, 0xd0, 0x0c, 0x18];
  var plaintext = fqConcat(header, rev, FQ_HIGH_RAND);
  // AES-CBC 加密: key = md5(signKey[0:16]), iv = md5(signKey[16:])
  var k16 = fqConcat(FQ_SIGN_KEY.slice(0, 16));
  var keyHex = fqMD5BytesHex(k16);
  var iv16 = fqConcat(FQ_SIGN_KEY.slice(16));
  var ivHex = fqMD5BytesHex(iv16);
  // AES-CBC 加密 plaintext（Packages Cipher）
  var cipher = Packages.javax.crypto.Cipher.getInstance('AES/CBC/PKCS5Padding');
  var skey = new Packages.javax.crypto.spec.SecretKeySpec(fqBytesToJavaArr(fqHexToBytes(keyHex)), 'AES');
  var ivSpec = new Packages.javax.crypto.spec.IvParameterSpec(fqBytesToJavaArr(fqHexToBytes(ivHex)));
  cipher.init(Packages.javax.crypto.Cipher.ENCRYPT_MODE, skey, ivSpec);
  var ct = fqJavaArrToBytes(cipher.doFinal(fqBytesToJavaArr(plaintext)));
  var result = fqConcat(FQ_LOW_RAND, ct);
  return fqBytesToB64(result);
}
function fqBytesToStr(bytes) {
  var s = new Packages.java.lang.String(fqBytesToJavaArr(bytes), 'UTF-8');
  return String(s);
}

function fqGetLadon(timestamp, aid) {
  aid = aid || FQ_AID;
  var randomBytes = [];
  for (var i = 0; i < 4; i++) randomBytes.push(Math.floor(Math.random() * 256));
  var plaintext = fqStrToBytes(timestamp + '-' + FQ_LICENSE_ID + '-' + aid);
  // key = md5(random || aid) 的 hex 文本作为字节
  var input = fqConcat(randomBytes, fqStrToBytes(aid));
  var keyHex = fqMD5BytesHex(input);
  var keyBytes = fqStrToBytes(keyHex);
  var encrypted = fqSpeckEnc(keyBytes, plaintext);
  var result = fqConcat(randomBytes, encrypted);
  return fqBytesToB64(result);
}

function fqSignRequest(url, body) {
  var qIdx = url.indexOf('?');
  var rawQuery = qIdx >= 0 ? url.substr(qIdx + 1) : '';
  var hasBody = body && body.length > 0;
  var xssStub = '';
  if (hasBody) xssStub = fqMD5Hex(body);
  var now = Date.now();
  var ts = Math.floor(now / 1000);
  var params = {};
  rawQuery.split('&').forEach(function(kv) {
    var p = kv.split('=');
    if (p.length === 2) params[decodeURIComponent(p[0])] = decodeURIComponent(p[1]);
  });
  var aid = params['aid'] || FQ_AID;
  var headers = {
    'x-argus': fqGetArgus(rawQuery, xssStub, ts),
    'x-ladon': fqGetLadon(ts, aid),
    'x-khronos': String(ts),
    'x-ss-req-ticket': String(now),
  };
  if (hasBody) headers['X-SS-STUB'] = xssStub;
  return headers;
}

