  for (var i = be.length; i > 0; i -= 2) rev += be.slice(i - 2, i);
  var idBytes = fqHexToBytes(rev).slice(0, 8);
  var iv = [];
  for (var i = 0; i < 16; i++) iv.push(Math.floor(Math.random() * 256));
  var enc = fqAesEncrypt(FQ_SHARED_KEY, iv, idBytes);
  return JSON.stringify({ content: fqBytesToB64(fqConcat(iv, enc)) });
}
