// 单段/碎片清理（与原 clean 链一致）
function fqCleanSeg(seg) {
  return seg.replace(/<br\s*\/?>/g, "\n").replace(/<[^>]+>/g, "").replace(/&nbsp;/g, " ").replace(/&amp;/g, "&").replace(/&quot;/g, "\"").replace(/&lt;/g, "<").replace(/&gt;/g, ">").replace(/\n{3,}/g, "\n\n").trim();
}

// 段落化清理：按 <p idx="N"> 切段，count>0 的段末插入评论泡（img 直接内联进正文）
function fqCleanWithPara(text, ideaMap, itemId, bookId, version) {
  text = text.replace(/<h1[^>]*>[\s\S]*?<\/h1\s*>/gi, "").replace(/<h1[^>]*>/gi, "");
  var re = /<p\b([^>]*)>([\s\S]*?)<\/p\s*>/g;
  var out = [];
  var last = 0;
  var m;
  while ((m = re.exec(text)) !== null) {
    var gap = text.slice(last, m.index);
    last = m.index + m[0].length;
    var gapC = fqCleanSeg(gap);
    if (gapC) out.push(gapC);
    var attrs = m[1] || "";
    var inner = m[2] || "";
    var idm = attrs.match(/idx\s*=\s*["']?(\d+)/);
    var idx = idm ? idm[1] : "";
    var seg = fqCleanSeg(inner);
    if (seg) {
      var cnt = (idx && ideaMap[idx] > 0) ? ideaMap[idx] : 0;
      if (cnt > 0) {
        var click = fqBuildReviewClick(itemId, bookId, idx, version);
        seg += "<img src=\"" + fqReviewBubble(cnt) + ",{\"style\":\"text\",\"type\":\"qd\",\"click\":\"" + click + "\"}\" >";
      }
      out.push(seg);
    }
  }
  out.push(fqCleanSeg(text.slice(last)));
  return out.join("\n");
}
function fqGetTextChapter(dev, key, itemId) {
  var url = "https://reading.snssdk.com/reading/reader/full/v?" + fqBaseQuery(dev) + "&item_id=" + itemId + "&req_type=1";
  var h = fqSignRequest(url, "");
  var hh = {
    "x-argus": new Packages.java.lang.String(String(h["x-argus"])),
    "x-ladon": new Packages.java.lang.String(String(h["x-ladon"])),
    "x-khronos": new Packages.java.lang.String(String(h["x-khronos"])),
    "x-ss-req-ticket": new Packages.java.lang.String(String(h["x-ss-req-ticket"])),
    "user-agent": new Packages.java.lang.String(String("com.dragon.read"))
  };
  var resp = this.java.get(url, hh);
  var cf = JSON.parse(String(resp.body()));
  if(cf.code!==0)throw new Error('官方正文拒绝 code='+cf.code+'；请在官方客户端确认章节可读权限'); var j = cf.data;
  if (!j || !j.content || j.content === "Invalid") return { title: "", content: "" };
  if (j.key_version && this.source.get("fq_kv") && String(j.key_version) !== this.source.get("fq_kv")) {
    this.source.put("fq_key", "");
    key = fqGetKey.call(this, dev);
  }
  var cb = fqB64ToBytes(j.content);
  var plain = fqAesDecrypt(key, cb.slice(0, 16), cb.slice(16));
  if (j.compress_status === 1) plain = fqGunzipBytes(plain);
  var text = fqBytesToStr(plain);
  var titleM = text.match(/<h1[^>]*>([^<]*)<\/h1>/);
  var title = titleM ? titleM[1] : (j.novel_data ? j.novel_data.title : "");
  var fqImgs = [];
  // 番茄部分章节正文内嵌排版 CSS（.volumePicture/.pageBg/.chapterTitle 等），
  // 必须连同 <style> 内容一起剥离，否则会以纯文本形式漏进正文。
  text = text.replace(/<style[^>]*>[\s\S]*?(?:<\/style\s*>|$)/gi, "")
             .replace(/<script[^>]*>[\s\S]*?(?:<\/script\s*>|$)/gi, "")
             .replace(/<!--[\s\S]*?-->/g, "")
             .replace(/<(?:link|meta)[^>]*>/gi, "");
  text = text.replace(/<image[^>]*xlink:href\s*=\s*["']([^"']+)["'][^>]*>/gi, function(tag, href) {
    return '<img src="' + href + '">';
  });
  text = text.replace(/<img[^>]*>/gi, function(tag) {
    var sm = tag.match(/src\s*=\s*["']([^"']+)["']/i);
    var u = sm ? sm[1] : "";
    u = u.replace(/&amp;/g, "&").replace(/&#38;/g, "&").trim();
    if (!u) return "";
    if (u.indexOf("//") === 0) u = "https:" + u;
    else if (u.indexOf("http://") === 0) u = "https://" + u.slice(7);
    fqImgs.push(u);
    return "\u0001FQIMG" + (fqImgs.length - 1) + "\u0001";
  });
  var clean;
  var ideaMap = {};
  try { ideaMap = fqGetIdeaList.call(this, dev, itemId); } catch (e) { ideaMap = {}; }
  if (Object.keys(ideaMap).length > 0) {
    clean = fqCleanWithPara(text, ideaMap, itemId,
      (j.novel_data ? String(j.novel_data.book_id) : ""),
      (j.novel_data ? String(j.novel_data.version) : ""));
  } else {
    clean = text.replace(/<h1[^>]*>.*?<\/h1>/g, "").replace(/<p[^>]*>/g, "\n").replace(/<\/p>/g, "").replace(/<br\s*\/?>/g, "\n").replace(/<[^>]+>/g, "").replace(/&nbsp;/g, " ").replace(/&amp;/g, "&").replace(/&quot;/g, "\"").replace(/&lt;/g, "<").replace(/&gt;/g, ">").replace(/\n{3,}/g, "\n\n").trim();
  }
  clean = fqDecode(clean);
  clean = clean.replace(/\u0001FQIMG(\d+)\u0001/g, function(_, idx) {
    var u = fqImgs[parseInt(idx, 10)];
    return u ? ("\n<img src=\"" + u + "\">\n") : "";
  });
  // 兜底：style 标签缺失/未闭合时，清掉残留的 CSS 规则块（@media 与 .sel/#id { ... }）
  clean = clean.replace(/@media[^{]*\{(?:[^{}]|\{[^{}]*\})*\}/g, "\n");
  for (var _ci = 0; _ci < 3; _ci++) {
    clean = clean.replace(/(^|\n)[ \t]*[.#@][\w\-.#:\s,>+~\[\]="']*\{[^{}]*\}[ \t]*(?=\n|$)/g, "\n");
  }
  clean = clean.replace(/[ \t]+\n/g, "\n").replace(/\n{3,}/g, "\n\n").trim();
  return { title: title, content: clean };
}
function fqGetAudioChapter(dev, itemId) {
  var url = "https://reading.snssdk.com/reading/reader/audio/playinfo/?tone_id=0&item_ids=" + itemId + "&pv_player=-1&aid=3040&device_platform=android&device_id=" + dev.device_id + "&iid=" + dev.install_id + "&ac=wifi&channel=0&app_name=novelapp&version_code=65432&version_name=6.5.4.32&device_type=unknown&os_version=10";
  var h = fqSignRequest(url, "");
  var hh = {
    "x-argus": new Packages.java.lang.String(String(h["x-argus"])),
    "x-ladon": new Packages.java.lang.String(String(h["x-ladon"])),
    "x-khronos": new Packages.java.lang.String(String(h["x-khronos"])),
    "x-ss-req-ticket": new Packages.java.lang.String(String(h["x-ss-req-ticket"])),
    "user-agent": new Packages.java.lang.String(String("com.dragon.read"))
  };
  var resp = this.java.get(url, hh);
  var body = String(resp.body());
  var cf;
  try { cf = JSON.parse(body); } catch (e) { return ""; }
  var audioUrl = "";
  var data = cf.data;
  if (data && Array.isArray(data) && data[0] && data[0].main_url) {
    audioUrl = data[0].main_url;
  } else if (data && data.video_model_infos) {
    for (var i = 0; i < data.video_model_infos.length; i++) {
      var info = data.video_model_infos[i];
      if (!info.video_model) continue;
      try {
        var model = JSON.parse(info.video_model);
        var vlist = model.video_list || [];
        for (var j = 0; j < vlist.length; j++) {
          if (vlist[j] && vlist[j].main_url) { audioUrl = vlist[j].main_url; break; }
        }
      } catch (e) {}
      if (audioUrl) break;
    }
  }
  return audioUrl;
}


