// fq_click_logic.js —— 评论泡 click 逻辑源码（被构建脚本 JSON 转义后注入书源）
// 重要约束：本文件内不得出现裸单引号（选项 JSON 用单引号包裹 click 值），
// 字符串一律双引号；正则中的单引号用 \x27。
// 运行环境为 BookImgClick 独立 evalJS：java/source/book/chapter/result 已注入，无正文函数。
// 段评弹窗（BottomWebViewDialog）在 preloadJs 非空时激活 WebJsExtensions 桥：
// 页内 run(js) 以 java/source/cache 绑定 + jsLib 原型链执行，可回调本文件全部函数。

function fqEsc(s) {
  s = String(s == null ? "" : s);
  return s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/\x27/g, "&#39;");
}

function fqFmtTime(ts) {
  var t = Number(ts);
  if (!t) return "";
  var diff = Math.floor(Date.now() / 1000) - t;
  if (diff < 60) return "刚刚";
  if (diff < 3600) return Math.floor(diff / 60) + "分钟前";
  if (diff < 86400) return Math.floor(diff / 3600) + "小时前";
  if (diff < 2592000) return Math.floor(diff / 86400) + "天前";
  var d = new Date(t * 1000);
  return (d.getMonth() + 1) + "月" + d.getDate() + "日";
}

