// 供桥 run() 调用：主评论翻页，返回新增 .item 片段 HTML（数据 JSON）
var fqRunMore = function (itemId, bookId, paraIdx, itemVersion, cursor) {
  try {
    var dev = { device_id: String(this.source.get("fq_did") || ""), install_id: String(this.source.get("fq_iid") || "") };
    if (!dev.device_id || dev.device_id === "0") throw new Error("设备未注册");
    if (!String(itemId || "")) throw new Error("段落参数缺失，请重开段评");
    var key = "fqrev_" + itemId + "_" + paraIdx;
    var prev = [];
    try { var p = JSON.parse(this.cache.getFromMemory(key) || "{}"); prev = p.list || []; } catch (e) {}
    var url = "https://reading.snssdk.com/novel/commentapi/comment/list/" + itemId + "/v1?" + fqBaseQuery(dev);
    var biz = { para_index: parseInt(paraIdx, 10), item_version: itemVersion, book_id: bookId };
    var body = { group_id: itemId, comment_source: 2, server_channel: 0, group_type: 15, comment_type: 1, sort: 1, count: 20, business_param: biz, cursor: cursor };
    var bodyStr = JSON.stringify(body);
    var h = fqSignRequest(url, bodyStr);
    var resp = this.java.post(url, bodyStr, fqRevHeaders(h));
    var j = JSON.parse(String(resp.body()));
    if (!(j && j.code === 0 && j.data)) throw new Error(j ? (j.message || "code=" + j.code) : "空响应");
    var list = j.data.data_list || [];
    var info = j.data.common_list_info || {};
    var merged = prev.concat(list);
    try { this.cache.putMemory(key, JSON.stringify({ list: merged, cursor: info.cursor || "", hasMore: !!info.has_more })); } catch (e) {}
    var html = fqRender(list, { paraIdx: paraIdx, itemId: itemId, bookId: bookId, ver: itemVersion, hasMore: !!info.has_more, cursor: info.cursor || "" });
    var mB = html.indexOf("<body>");
    var mE = html.indexOf("</body>");
    html = (mB >= 0 && mE > mB) ? html.substring(mB + 6, mE) : html;
    html = html.replace(/^<div class="hdr">[\s\S]*?<\/div>/, "");
    // 裁剪掉本页末端的翻页/到底 div，只留纯 .item 片段，避免残留样式或冗余节点
    var mCut = html.indexOf('<div class="more">');
    var nCut = html.indexOf('<div class="note">');
    var cut = -1;
    if (mCut >= 0 && (cut < 0 || mCut < cut)) cut = mCut;
    if (nCut >= 0 && (cut < 0 || nCut < cut)) cut = nCut;
    if (cut >= 0) html = html.substring(0, cut);
    var done = !(info.has_more && info.cursor);
    var nextCursor = done ? "" : String(info.cursor || "");
    try { this.cache.putMemory(key, JSON.stringify({ list: merged, cursor: nextCursor, hasMore: !done })); } catch (e) {}
    return JSON.stringify({ ok: true, html: html, done: done, cursor: nextCursor, loaded: list.length });
  } catch (e) {
    return JSON.stringify({ ok: false, msg: String((e && e.message) || e) });
  }
};

// 生成一个可点击的“胶囊”触发小图标（label 文案），img 选项为标准 JSON（click 内层单引号）
// 仅用于正文页气泡（阅读器解析 src 选项）；弹窗内按钮已改用 .fqbtn 真元素
function fqTriggerImg(label, click) {
  var w = 110, pad = 12;
  var fs = 12;
  var lw = 0;
  for (var i = 0; i < label.length; i++) lw += label.charCodeAt(i) > 255 ? fs : fs * 0.58;
  w = Math.max(60, Math.ceil(lw) + pad * 2);
  var svg = '<svg xmlns="http://www.w3.org/2000/svg" width="' + w + '" height="28" viewBox="0 0 ' + w + ' 28">' +
    '<rect width="100%" height="100%" rx="14" fill="#EDF0F6"/>' +
    '<text x="' + (w / 2) + '" y="15" font-family="Arial,sans-serif" font-size="' + fs + '" fill="#576B95" text-anchor="middle" dominant-baseline="middle">' + fqEsc(label) + '</text></svg>';
  var b = [];
  for (var j = 0; j < svg.length; j++) b.push(svg.charCodeAt(j));
  var src = "data:image/svg+xml;base64," + fqBytesToB64(b);
  return "<img src=\"" + src + ",{\"style\":\"text\",\"type\":\"qd\",\"click\":\"" + click + "\"}\" >";
}

