// 共用请求头
function fqRevHeaders(h) {
  var hh = {
    "x-argus": new Packages.java.lang.String(String(h["x-argus"])),
    "x-ladon": new Packages.java.lang.String(String(h["x-ladon"])),
    "x-khronos": new Packages.java.lang.String(String(h["x-khronos"])),
    "x-ss-req-ticket": new Packages.java.lang.String(String(h["x-ss-req-ticket"])),
    "X-SS-STUB": new Packages.java.lang.String(String(h["X-SS-STUB"])),
    "user-agent": new Packages.java.lang.String("com.dragon.read"),
    "Content-Type": new Packages.java.lang.String("application/json; charset=utf-8")
  };
  return hh;
}

// 拉取某条主评论的楼中楼回复列表 reply/list/{comment_id}/v1
function fqFetchReplies(dev, itemId, bookId, commentId, want) {
  var url = "https://reading.snssdk.com/novel/commentapi/reply/list/" + commentId + "/v1?" + fqBaseQuery(dev);
  var all = [];
  var total = want || 0;
  var count = Math.min(want || 0, 20); if (count < 1) count = 20;
  var body = { group_id: itemId, comment_id: commentId, comment_source: 502, server_channel: 0, group_type: 15, comment_type: 1, count: count, business_param: { book_id: bookId } };
  var bodyStr = JSON.stringify(body);
  var h = fqSignRequest(url, bodyStr);
  var resp = this.java.post(url, bodyStr, fqRevHeaders(h));
  var j = JSON.parse(String(resp.body()));
  if (j && j.code === 0 && j.data) {
    all = j.data.reply_list || [];
    var info = j.data.common_list_info || {};
    if (info && info.total != null && Number(info.total) > 0) total = Number(info.total);
  }
  return { list: all, total: total };
}

// 楼中楼线程织树
function fqThread(replies) {
  var byId = {};
  var roots = [];
  var i;
  for (i = 0; i < replies.length; i++) {
    if (replies[i]) { byId[replies[i].reply_id] = replies[i]; replies[i].__ch = replies[i].__ch || []; }
  }
  for (i = 0; i < replies.length; i++) {
    var r = replies[i];
    if (!r) continue;
    var pid = r.reply_to_reply_id;
    var parent = (pid && byId[pid]) || null;
    if (parent) parent.__ch.push(r);
    else roots.push(r);
  }
  return roots;
}

function fqReplyRows(replies, depth) {
  var out = "";
  var n = (replies && replies.length) || 0;
  for (var i = 0; i < n; i++) out += fqReplyRow(replies[i], depth);
  return out;
}

// 渲染一条楼中楼回复（含 @被回复人 与嵌套线程子回复）；reply/list 对象字段为大写 Common，兼容小写 common
function fqReplyRow(rep, depth) {
  var C = (rep && (rep["Common"] || rep["common"])) || {};
  var content = C["content"] || {};
  var ui = C["user_info"] || {};
  var bi = ui["base_info"] || {};
  var text = String(content["text"] || "").trim();
  if (!text) return "";
  text = fqEsc(text);
  var name = fqEsc(bi["user_name"] || "匿名");
  var avatar = String(bi["user_avatar"] || "");
  var t = fqFmtTime(C["create_timestamp"]);
  var digg = Number((rep.stat || {})["digg_count"]) || 0;
  var at = "";
  var rtu = ((rep.reply_to_user_info || {})["base_info"]) || {};
  if (rtu["user_name"]) at = "<span class=\"ra\"> 回复 @" + fqEsc(rtu["user_name"]) + "</span>";
  var pad = depth > 0 ? " style=\"margin-left:" + (12 * (depth > 2 ? 2 : depth)) + "px\"" : "";
  var kids = [];
  if (rep.__ch && rep.__ch.length) for (var k = 0; k < rep.__ch.length; k++) kids.push(rep.__ch[k]);
  if (rep.sub_reply && rep.sub_reply.length) for (var m = 0; m < rep.sub_reply.length; m++) kids.push(rep.sub_reply[m]);
  var sub = kids.length ? fqReplyRows(kids, depth + 1) : "";
  return "<div class=\"fqreply\"" + pad + "><div class=\"rrow\">" +
    (avatar ? "<img class=\"rava\" src=\"" + avatar + "\">" : "<div class=\"rava\"></div>") +
    "<div class=\"rbody\"><div class=\"rname\">" + name + at + "</div>" +
    "<div class=\"rtime\">" + t + "</div>" +
    "<div class=\"rtx\">" + text + "</div>" +
    (digg ? "<div class=\"rd\"><b>👍 " + digg + "</b></div>" : "") +
    "</div></div>" + sub + "</div>";
}


